namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string DepartmentCode { get; set; } = string.Empty;
    public string CourseNumber { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }

    public string FullCode => $"{DepartmentCode} {CourseNumber}";
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and human civilization." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and education. She holds a Ph.D. from MIT and previously worked at Google.", IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming).", Credits = 4, Schedule = "TTh 10:30–11:45 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park specializes in algorithm optimization and has published extensively in computational complexity theory.", IsFeatured = true },
            new() { Id = 3, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "310", Title = "Database Systems", Description = "Relational database design, SQL, transaction processing, and an introduction to NoSQL systems.", Credits = 3, Schedule = "MWF 1:00–1:50 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez worked as a database architect at Oracle for 10 years before joining academia.", IsFeatured = false },
            new() { Id = 4, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "450", Title = "Machine Learning", Description = "Supervised and unsupervised learning, neural networks, and practical applications using modern frameworks.", Credits = 4, Schedule = "TTh 2:00–3:15 PM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and education. She holds a Ph.D. from MIT and previously worked at Google.", IsFeatured = true },
            new() { Id = 5, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications.", Credits = 4, Schedule = "MWF 8:00–8:50 AM", InstructorName = "Prof. Robert Klein", InstructorBio = "Prof. Klein is an award-winning educator with a passion for making calculus accessible to all students.", IsFeatured = true },
            new() { Id = 6, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "201", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications.", Credits = 3, Schedule = "TTh 9:00–10:15 AM", InstructorName = "Dr. Anika Patel", InstructorBio = "Dr. Patel researches applied mathematics and has consulted for NASA on trajectory optimization.", IsFeatured = false },
            new() { Id = 7, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "301", Title = "Probability & Statistics", Description = "Random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "MWF 11:00–11:50 AM", InstructorName = "Dr. Anika Patel", InstructorBio = "Dr. Patel researches applied mathematics and has consulted for NASA on trajectory optimization.", IsFeatured = false },
            new() { Id = 8, DepartmentId = 3, DepartmentCode = "PHYS", CourseNumber = "101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions.", Credits = 4, Schedule = "MWF 10:00–10:50 AM + Lab F 2:00–4:00 PM", InstructorName = "Dr. Thomas Nguyen", InstructorBio = "Dr. Nguyen is an experimental physicist who has contributed to CERN's particle detection research.", IsFeatured = false },
            new() { Id = 9, DepartmentId = 3, DepartmentCode = "PHYS", CourseNumber = "201", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "TTh 1:00–2:15 PM + Lab W 3:00–5:00 PM", InstructorName = "Dr. Thomas Nguyen", InstructorBio = "Dr. Nguyen is an experimental physicist who has contributed to CERN's particle detection research.", IsFeatured = false },
            new() { Id = 10, DepartmentId = 4, DepartmentCode = "ENG", CourseNumber = "110", Title = "Academic Writing", Description = "Develop skills in argumentation, research writing, and critical analysis of texts.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", InstructorName = "Prof. Diana Frost", InstructorBio = "Prof. Frost is a published author and former editor at The Atlantic.", IsFeatured = false },
            new() { Id = 11, DepartmentId = 4, DepartmentCode = "ENG", CourseNumber = "250", Title = "American Literature", Description = "Survey of major American literary works from the colonial period to the present.", Credits = 3, Schedule = "TTh 11:00 AM–12:15 PM", InstructorName = "Prof. Diana Frost", InstructorBio = "Prof. Frost is a published author and former editor at The Atlantic.", IsFeatured = true },
            new() { Id = 12, DepartmentId = 5, DepartmentCode = "HIST", CourseNumber = "101", Title = "World History to 1500", Description = "Survey of human civilizations from prehistory through the late medieval period.", Credits = 3, Schedule = "MWF 2:00–2:50 PM", InstructorName = "Dr. Marcus Webb", InstructorBio = "Dr. Webb is an archaeologist and historian who has led excavations in Egypt and Mesopotamia.", IsFeatured = false },
            new() { Id = 13, DepartmentId = 5, DepartmentCode = "HIST", CourseNumber = "220", Title = "Modern European History", Description = "Europe from the French Revolution to the present day, covering political, social, and cultural transformations.", Credits = 3, Schedule = "TTh 3:30–4:45 PM", InstructorName = "Dr. Elena Volkov", InstructorBio = "Dr. Volkov specializes in 20th-century European political movements and is the author of three acclaimed books.", IsFeatured = false }
        };
    }

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public IReadOnlyList<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.FullCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database
        return !string.IsNullOrWhiteSpace(request.StudentName)
            && !string.IsNullOrWhiteSpace(request.StudentId)
            && request.CourseId > 0
            && _courses.Any(c => c.Id == request.CourseId);
    }
}

