+    {
+        if (CourseId.HasValue && Model.CourseId == 0)
+        {
+            Model.CourseId = CourseId.Value;
+        }
+    }
+
+    protected override void OnParametersSet()
+    {
+        // Check if this is a POST (form submission)
+        if (!string.IsNullOrWhiteSpace(Model.StudentName) || !string.IsNullOrWhiteSpace(Model.StudentId) || Model.CourseId > 0)
+        {
+            if (string.IsNullOrWhiteSpace(Model.StudentName) || string.IsNullOrWhiteSpace(Model.StudentId) || Model.CourseId == 0)
+            {
+                ValidationError = "Please fill out all fields.";
+                return;
+            }
+
+            if (Catalog.SubmitEnrollmentRequest(Model))
+            {
+                Submitted = true;
+            }
+            else
+            {
+                ValidationError = "Unable to process your request. Please verify the selected course.";
+            }
+        }
+    }
+}
